'nacos','192.168.1.63','','e7a3ac8d-49e9-4ae7-ac81-56ce1cc9ca10','通用配置',NULL,NULL,'yaml',NULL,''),(29,'xfglpt-gateway-prod.yml','DEFAULT_GROUP','spring:\n  redis:\n    host: 192.168.1.56\n    port: 6379\n    password: \n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: xfglpt-auth\n          uri: lb://xfglpt-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: xfglpt-gen\n          uri: lb://xfglpt-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 定时任务\n        - id: xfglpt-job\n          uri: lb://xfglpt-job\n          predicates:\n            - Path=/schedule/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: xfglpt-system\n          uri: lb://xfglpt-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: xfglpt-file\n          uri: lb://xfglpt-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n','64dd3eceb6ee22ae7cd7291a8c9ac8ea','2025-03-27 15:44:40','2025-03-27 15:44:40','nacos','192.168.1.63','','e7a3ac8d-49e9-4ae7-ac81-56ce1cc9ca10','网关模块',NULL,NULL,'yaml',NULL,''),(30,'xfglpt-auth-prod.yml','DEFAULT_GROUP','spring:\n  redis:\n    host: 192.168.1.56\n    p