plier\n          uri: lb://xfglpt-supplier\n          predicates:\n            - Path=/supplier/**\n          filters:\n            - StripPrefix=1\n      globalcors:\n        corsConfigurations:\n          \'[/**]\':\n            allowedOriginPatterns: \"*\"\n            allowed-methods: \"*\"\n            allowed-headers: \"*\"\n            allow-credentials: true\n            exposedHeaders: \"Content-Disposition,Content-Type,Cache-Control\"\n\n\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n      - /school/jzbuy/opinions/config\n      - /system/xfptnotice/**\n      - /school/jzbuy/opinions\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n      - /system/open/**\n      - /school/question/config/content\n      - /school/questionnaireResult\n      - /school/questionnaireResult/selIpAddress\n      - /system/dict/data/type/**\n      - /school/school/open/**\n      - /school/team/meeting/importUserName\n      - /school/question/config/selectName\n      - /school/questionnaireSurvey/exportResultExcel\n      - /school/simOpen/redirecturi\n      - /system/sms/test\n      - /system/sms/sendSms\n      - /system/sms/smsLogin\n      - /system/user/resetPwdSendSms\n      - /system/sms/userEncrypt\n      - /school/suppliceContractSon/dateEnc\n      - /system/getRandom\n      - /system/verifyCertAndSign\n      - /school/**\n      - /system/dict/**\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n','dd5df7d354620ea40627d986b4997a37','2026-04-23 06:25:53','2026-04-23 06:25:53',NULL,'127.0.0.1','U','5e3e155d-73b2-4a36-ab8b-e54454e8b351',''),(17,220,'xfglpt-file-dev.yml','DEFAULT_GROUP','','# 本地文件上传    \nfile:\n    domain: http://192.168.1.110:9300\n    path: /Library/dev/ruoyi/uploadPath\n    prefix: /filestatics\n\n# FastDFS配置\nfdfs:\n  